    private widget.ButtonBig createMenuButton(String iconPath, String text, String name, java.awt.Dimension preferedSize, java.awt.event.ActionListener actionListener) {
        widget.ButtonBig button = new widget.ButtonBig();
        button.setIcon(new javax.swing.ImageIcon(getClass().getResource(iconPath)));
        button.setText(text);
        button.setIconTextGap(0);
        button.setName(name);
        button.setPreferredSize(preferedSize);
        button.addActionListener(actionListener);
        return button;
    }

